package com.gymflow.app;
import android.content.Intent; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity;
public class RegisterActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout r=Ui.page(this);Ui.backHeader(this,r,"Crear cuenta");EditText email=Ui.input(this,"Email del dueño");r.addView(email);EditText pass=Ui.input(this,"Contraseña (mínimo 8 caracteres)");pass.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);r.addView(pass);EditText gym=Ui.input(this,"Nombre del gimnasio");r.addView(gym);TextView state=Ui.subtitle(this,"Cada cuenta tendrá sus propios socios, pagos, máquinas y rutinas.");r.addView(state);Button go=Ui.button(this,"Crear GymFlow");r.addView(go);go.setOnClickListener(v->{String e=email.getText().toString().trim(),p=pass.getText().toString(),g=gym.getText().toString().trim();if(e.isEmpty()||p.length()<8||g.isEmpty()){Toast.makeText(this,"Completá los datos y usá una contraseña de 8 caracteres o más",Toast.LENGTH_LONG).show();return;}go.setEnabled(false);state.setText("Creando cuenta...");Cloud.signUp(this,e,p,(code,body)->{if(code>=200&&code<300){getSharedPreferences("gymflow",0).edit().putString("pending_gym_name",g).apply();if(Session.logged(this)){startActivity(new Intent(this,SetupGymActivity.class));finish();}else{state.setText("Cuenta creada. Revisá tu email para confirmar y después iniciá sesión.");go.setEnabled(true);}}else{state.setText("No se pudo crear: "+Cloud.err(body));go.setEnabled(true);}});});setContentView(r);}
}
